class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free(x):
            square_free = 1
            # Handle factor 2
            count = 0
            while x % 2 == 0:
                count += 1
                x //= 2
            if count % 2 == 1:
                square_free *= 2
            # Handle odd factors
            d = 3
            while d * d <= x:
                count = 0
                while x % d == 0:
                    count += 1
                    x //= d
                if count % 2 == 1:
                    square_free *= d
                d += 2
            if x > 1:
                square_free *= x
            return square_free

        groups = defaultdict(int)
        for num in nums:
            sf = get_square_free(num)
            groups[sf] += num

        return max(groups.values())

