            for j in range(n):
                if i != j:
                    common = len(sets[i] & sets[j])
                    if common >= k:
                        adj[i].append(j)
        # Find connected components using DFS
        visited = [False] * n
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1
                # Use stack for DFS
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
        return count
